DROP POLICY IF EXISTS bp_tenant_isolation ON proc.bp_triage_run;
CREATE POLICY bp_tenant_isolation ON proc.bp_triage_run
  USING (tenant_id = current_setting('app.tenant_id', true)
       OR current_setting('app.system', true) = 'on')
  WITH CHECK (tenant_id = current_setting('app.tenant_id', true)
       OR current_setting('app.system', true) = 'on');
DROP POLICY IF EXISTS bp_support_read ON proc.bp_triage_run;
CREATE POLICY bp_support_read ON proc.bp_triage_run FOR SELECT TO procwise_readonly
  USING (nullif(current_setting('app.support_reason', true), '') IS NOT NULL);

